        {"why": "reserved tail", "status": -3, "patch": patch(444, "I", 1)},
        {"why": "unknown gravity model", "status": -3, "patch": patch(4, "I", 3)},
        {"why": "NaN mass", "status": -3, "patch": patch(16, "d", float("nan"))},
        {"why": "zero mass", "status": -3, "patch": patch(16, "d", 0.0)},
